		"staging/features.yml",
		"staging/sandbox/sandbox.features.yml",
		"staging/sandbox/features.yaml",
	}
	assert.Len(t, filenames, 6)
	assert.ElementsMatch(t, filenames, expected)

	readers := make([]io.Reader, 0, 6)

	for _, f := range filenames {
