func (e Error) Error() string {
	return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column)
}

type multiError struct{ errors []error }

func (e multiError) Error() string {
	messages := make([]string, 0, len(e.errors))
	for _, err := range e.errors {
		messages = append(messages, err.Error())
	}
	return strings.Join(messages, "\n")
}
func (e multiError) Unwrap() []error { return e.errors }

// Unwrap returns the individual errors in err when it is a multi-error.
func Unwrap(err error) ([]error, bool) {
	var m interface{ Unwrap() []error }
	if !errors.As(err, &m) {
		return nil, false
	}
	return m.Unwrap(), true
}

