// ValidateReferences checks flag rule references and reports errors with source locations.
func ValidateReferences(file string, b []byte) error {
	var doc ext.Document
	if err := yaml.Unmarshal(b, &doc); err != nil {
		return multiError{errors: []error{locatedError(file, err.Error(), 1, 1)}}
	}
	found := referenceErrors(file, b, &doc)
	if len(found) == 0 {
		return nil
	}
	return multiError{errors: found}
}

// Validate validates a YAML file against our cue definition of features.
func (v FeaturesValidator) Validate(file string, b []byte) error {

	f, err := c_yaml.Extract("", b)
	if err != nil {
		return wrapValidationError(file, err)
	}

	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil {
		return wrapValidationError(file, err)
	}

	err = v.v.
		Unify(yv).
		Validate(cue.All(), cue.Concrete(true))

	var validationErrors []error
	for _, e := range cueerrors.Errors(err) {
		item := locatedError(file, e.Error(), 0, 0)
		if pos := cueerrors.Positions(e); len(pos) > 0 {
			p := pos[len(pos)-1]
			item.Location.Line, item.Location.Column = p.Line(), p.Column()
		}
		ensurePosition(&item)
		validationErrors = append(validationErrors, item)
	}

	// CUE validates shape and scalar constraints. Resolve rule references here,
	// using YAML node positions so each error points at the offending reference.
	if referenceErr := ValidateReferences(file, b); referenceErr != nil {
		if individual, ok := Unwrap(referenceErr); ok {
			validationErrors = append(validationErrors, individual...)
		} else {
			validationErrors = append(validationErrors, referenceErr)
		}
	}
	if len(validationErrors) != 0 {
		return multiError{errors: validationErrors}
	}
	return nil
}

func wrapValidationError(file string, err error) error {
	items := cueerrors.Errors(err)
	if len(items) == 0 {
		return multiError{errors: []error{locatedError(file, err.Error(), 1, 1)}}
	}
	validationErrors := make([]error, 0, len(items))
	for _, item := range items {
		validationErr := locatedError(file, item.Error(), 0, 0)
		if positions := cueerrors.Positions(item); len(positions) > 0 {
			position := positions[len(positions)-1]
			validationErr.Location.Line, validationErr.Location.Column = position.Line(), position.Column()
		}
		ensurePosition(&validationErr)
		validationErrors = append(validationErrors, validationErr)
	}
	return multiError{errors: validationErrors}
}

func locatedError(file, message string, line, column int) Error {
	return Error{Message: message, Location: Location{File: file, Line: line, Column: column}}
}
func ensurePosition(err *Error) {
	if err.Location.Line < 1 {
		err.Location.Line = 1
	}
	if err.Location.Column < 1 {
		err.Location.Column = 1
	}
}

func referenceErrors(file string, b []byte, doc *ext.Document) []error {
	var root yaml.Node
	if yaml.Unmarshal(b, &root) != nil || len(root.Content) == 0 {
		return nil
	}
	document := root.Content[0]
	segments := map[string]bool{}
	for _, segment := range doc.Segments {
		if segment != nil {
			segments[segment.Key] = true
		}
	}
	flagsNode := mappingValue(document, "flags")
	var result []error
	for flagIndex, flag := range doc.Flags {
		if flag == nil {
			continue
		}
		flagNode := sequenceItem(flagsNode, flagIndex)
		flagKey := ""
		if keyNode := mappingValue(flagNode, "key"); keyNode != nil {
			flagKey = keyNode.Value
		}
		variants := map[string]bool{}
		for _, variant := range flag.Variants {
			if variant != nil {
				variants[variant.Key] = true
			}
		}
		rulesNode := mappingValue(flagNode, "rules")
		for ruleIndex, rule := range flag.Rules {
			if rule == nil {
				continue
			}
			ruleNode := sequenceItem(rulesNode, ruleIndex)
			if rule.Segment != nil {
				switch segment := rule.Segment.IsSegment.(type) {
				case ext.SegmentKey:
					key := string(segment)
					if !segments[key] {
						result = append(result, positionedReferenceError(file, fmt.Sprintf("flag %s/%s rule %d references unknown segment %q", namespace(doc), flagKey, ruleIndex, key), mappingValue(ruleNode, "segment")))
					}
				case *ext.Segments:
					segmentNode := mappingValue(ruleNode, "segment")
					keysNode := mappingValue(segmentNode, "keys")
					for keyIndex, key := range segment.Keys {
						if !segments[key] {
							result = append(result, positionedReferenceError(file, fmt.Sprintf("flag %s/%s rule %d references unknown segment %q", namespace(doc), flagKey, ruleIndex, key), sequenceItem(keysNode, keyIndex)))
						}
					}
				}
			}
			distributionsNode := mappingValue(ruleNode, "distributions")
			for distributionIndex, distribution := range rule.Distributions {
				if distribution != nil && !variants[distribution.VariantKey] {
					distributionNode := sequenceItem(distributionsNode, distributionIndex)
					result = append(result, positionedReferenceError(file, fmt.Sprintf("flag %s/%s rule %d references unknown variant %q", namespace(doc), flagKey, ruleIndex, distribution.VariantKey), mappingValue(distributionNode, "variant")))
				}
			}
		}
